// ------------------------------------------------------------------ raffle actions

function buy(uint256 raffleSeed, uint256 buyerSeed, uint256 recipientSeed, uint256 countSeed) public {
    Raffle r = _raffle(raffleSeed);
    if (_tickets[address(r)].length >= MAX_TICKETS) return;
    Actor buyer = _actor(buyerSeed);
    Actor recipient = _actor(recipientSeed);
    uint128 count = uint128(_bound(countSeed, 1, 20));
    uint256 cost = uint256(count) * PRICE;
    usdc.mint(address(buyer), cost);
    buyer.exec(address(usdc), abi.encodeCall(usdc.approve, (address(r), cost)));
    uint128 totalBefore = r.totalEntries();
    uint128 countBefore = r.ticketCount();
    uint256 balBefore = usdc.balanceOf(address(r));
    bool expectOk = r.status() == IRaffle.Status.Active && block.timestamp < r.endTime()
        && _usdcMovable(address(buyer), address(r));
    (bool ok, bytes memory ret) = buyer.exec(address(r), abi.encodeCall(r.buyEntries, (address(recipient), count)));
    if (ok != expectOk) _fail("buy: outcome mismatch");
    if (!ok) return;
    uint256 ticketId = abi.decode(ret, (uint256));
    _tickets[address(r)].push(ticketId);
    ghost[address(r)].bought += cost;
    (uint128 first, uint128 last) = r.ticketRange(ticketId);
    if (ticketId != uint256(countBefore) + 1) _fail("buy: ticket id not sequential");
    if (first != totalBefore + 1 || last != totalBefore + count) _fail("buy: wrong range");
    if (r.ownerOf(ticketId) != address(recipient)) _fail("buy: wrong owner");
    if (usdc.balanceOf(address(r)) != balBefore + cost) _fail("buy: wrong payment");
    ++hits["buy"];
}

