/// ===================================================================================================================
/// F. Reentrancy by untrusted ticket recipients and prize contracts
/// ===================================================================================================================
contract F_ReentrancyTest is Fixture {
    function test_F1_ticketRecipientCannotReenterAnyGuardedEntryPoint() public {
